CREATE TABLE IF NOT EXISTS email_tracking_events (
  id SERIAL PRIMARY KEY,
  "prospectId" INTEGER,
  "messageId" TEXT NOT NULL,
  "eventType" TEXT NOT NULL,
  url TEXT,
  "occurredAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  raw JSONB,
  "createdAt" TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_email_tracking_prospect ON email_tracking_events ("prospectId");
CREATE INDEX IF NOT EXISTS idx_email_tracking_message ON email_tracking_events ("messageId");
CREATE INDEX IF NOT EXISTS idx_email_tracking_event_type ON email_tracking_events ("eventType");

